const HOOK_TIMEOUT_MS = 20000;
const NODE_BIN = process.env.EASY_CLAUDE_NODE || "node";

// opencode built-in tool ids -> Claude matcher names the hooks are written against.
const TOOL_ALIASES = {
  bash: ["Bash"],
  edit: ["Edit", "MultiEdit"],
  write: ["Write"],
  read: ["Read"],
  grep: ["Grep"],
  glob: ["Glob"],
  apply_patch: ["Edit", "Write", "MultiEdit", "NotebookEdit"],
  todowrite: ["TodoWrite", "TaskCreate", "TaskUpdate", "update_plan"],
  webfetch: ["WebFetch"],
  websearch: ["WebSearch"],
  question: ["AskUserQuestion"],
  skill: ["Skill"],
  lsp: ["LSP"],
};

function findRoot(start) {
  let current = start && String(start).trim() ? path.resolve(String(start)) : process.cwd();
  for (;;) {
    if (fs.existsSync(path.join(current, ".claude"))) return current;
    const parent = path.dirname(current);
    if (parent === current) return current;
    current = parent;
  }
}

// Host bridge boundary: resolve only the validated native capability and apply
// it to this hook child. The canonical verifier owns the startup-only detached
// repair decision; this launcher never installs software and never mutates the
// opencode host process environment.
function childEnvironment(root) {
  const env = { ...process.env, CLAUDE_PROJECT_DIR: root };
  const helperPath = path.join(root, ".claude", "hooks", "lib", "windows-git.cjs");
  try {
    if (!fs.existsSync(helperPath)) return env;
    const windowsGit = require(helperPath);
    const result = windowsGit.resolveWindowsGit();
    if (!result || result.outcome !== windowsGit.OUTCOMES.READY) return env;
    return windowsGit.withGitEnvironment(env, result.capability);
  } catch {
    return env;
  }
}

// Protocol delivery re-arms after a compaction (BR-PDL-02). opencode hook events carry no
// conversation record the delivery ledger could scan for the compaction, so on session.compacted
// the bridge reports it to the ledger directly. Best effort, like the Git capability above: a
// missing or failing lib costs one missed re-delivery, never the event.
function recordProtocolCompaction(root, sessionID) {
  if (!sessionID) return;
  const libPath = path.join(root, ".claude", "hooks", "lib", "protocol-delivery.cjs");
  try {
    if (!fs.existsSync(libPath)) return;
    const delivery = require(libPath);
    if (typeof delivery.recordCompaction !== "function") return;
    delivery.recordCompaction({ session_id: sessionID, cwd: root }, { projectRoot: root });
  } catch {
    /* fail-open: the skill's guide entries remain the path */
  }
}

function claudeToolNames(tool) {
  if (typeof tool !== "string" || tool.length === 0) return [String(tool ?? "")];
  if (Object.prototype.hasOwnProperty.call(TOOL_ALIASES, tool)) return TOOL_ALIASES[tool];
  return [tool];
}

// Claude matcher tokens: `*`, exact names, prefix globs (`mcp__github__*`), and
// `|`-separated alternatives. Claude's MCP matcher `mcp__<server>__*` maps to
// opencode's `<server>_<tool>` MCP tool id convention.
function matchToken(token, names) {
  if (!token) return false;
  if (token === "*") return true;
  if (token.startsWith("mcp__")) {
    const rest = token.slice("mcp__".length);
    const sep = rest.indexOf("__");
    const server = (sep === -1 ? rest : rest.slice(0, sep)).toLowerCase();
    const toolPart = sep === -1 ? "*" : rest.slice(sep + 2);
    if (!server) return false;
    return names.some((name) => {
      const lower = String(name).toLowerCase();
      if (!lower.startsWith(`${server}_`)) return false;
      if (toolPart === "*") return true;
      return lower === `${server}_${toolPart.toLowerCase()}`;
    });
  }
  const lowerToken = token.toLowerCase();
  return names.some((name) => {
    const lower = String(name).toLowerCase();
    if (lowerToken === lower) return true;
    if (lowerToken.endsWith("*") && lower.startsWith(lowerToken.slice(0, -1))) return true;
    return false;
  });
}

function matcherMatches(matcher, names) {
  if (!matcher || matcher === "*") return true;
  return matcher.split("|").some((raw) => matchToken(raw.trim(), names));
}

// Claude's handler `if` condition, checked in-process so a hook the condition excludes is never
// spawned (the bridge runs hooks one after another, so every avoided spawn saves a Node start).
// Supported form: `Read(<glob>)` — true when the tool is Read and `tool_input.file_path`, with `\`
// turned into `/`, matches the glob as given or relative to the project root. In the glob `**/`
// matches any directory prefix (including none), `**` anything, `*` and `?` stay within one path
// segment. Every other form returns true, so an unsupported condition can cost a spawn but never
// drops a hook. The glob only ever becomes an escaped regular expression; it is never run as code.
const READ_CONDITION = /^\s*Read\(\s*(\S(?:.*\S)?)\s*\)\s*$/;

function globToRegExp(glob) {
  let source = "";
  for (let index = 0; index < glob.length; index += 1) {
    const char = glob[index];
    if (char === "*" && glob[index + 1] === "*") {
      if (glob[index + 2] === "/") {
        source += "(?:.*/)?";
        index += 2;
      } else {
        source += ".*";
        index += 1;
      }
    } else if (char === "*") {
      source += "[^/]*";
    } else if (char === "?") {
      source += "[^/]";
    } else {
      source += char.replace(/[.+^${}()|[\]\\]/g, "\\$&");
    }
  }
  return new RegExp(`^${source}$`, process.platform === "win32" ? "i" : "");
}

function hookConditionHolds(condition, root, payload) {
  if (typeof condition !== "string" || !condition.trim()) return true;
  const match = READ_CONDITION.exec(condition);
  if (!match) return true;
  if (!payload || payload.tool_name !== "Read") return false;
  const filePath = payload.tool_input && payload.tool_input.file_path;
  if (typeof filePath !== "string" || !filePath) return false;
  const pattern = globToRegExp(match[1].replaceAll("\\", "/"));
  const candidates = [filePath.replaceAll("\\", "/")];
  if (path.isAbsolute(filePath)) {
    const relative = path.relative(root, filePath);
    if (relative && !relative.startsWith("..") && !path.isAbsolute(relative)) candidates.push(relative.replaceAll("\\", "/"));
  }
  return candidates.some((candidate) => pattern.test(candidate));
}

// opencode argument names -> the Claude tool_input field names hooks read.
function toClaudeToolInput(tool, args) {
  const source = args && typeof args === "object" ? args : {};
  const input = { ...source };
  if (source.filePath !== undefined) {
    input.file_path = source.filePath;
    if (input.path === undefined) input.path = source.filePath;
  }
  if (source.oldString !== undefined) input.old_string = source.oldString;
  if (source.newString !== undefined) input.new_string = source.newString;
  if (source.replaceAll !== undefined) input.replace_all = source.replaceAll;
  if (source.patchText !== undefined) input.patch = source.patchText;
  return input;
}

function applyUpdatedInput(args, updatedInput) {
  if (!args || typeof args !== "object" || !updatedInput || typeof updatedInput !== "object") return;
  const reverse = {
    file_path: "filePath",
    old_string: "oldString",
    new_string: "newString",
    replace_all: "replaceAll",
  };
  for (const [key, value] of Object.entries(updatedInput)) {
    args[reverse[key] || key] = value;
  }
}

function parseJsonOutput(stdout) {
  if (typeof stdout !== "string" || stdout.trim().length === 0) return null;
  try {
    return JSON.parse(stdout);
  } catch {
    return null;
  }
}

function runHook(root, hookPath, payload) {
  return new Promise((resolve) => {
    let child;
    try {
      child = spawn(NODE_BIN, [hookPath], {
        cwd: root,
        env: childEnvironment(root),
        stdio: ["pipe", "pipe", "pipe"],
        windowsHide: true,
      });
    } catch (error) {
      resolve({ code: null, stdout: "", stderr: `${error && error.message ? error.message : error}`, spawnError: true });
      return;
    }

    let stdout = "";
    let stderr = "";
    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(result);
    };
    const timer = setTimeout(() => {
      try {
        child.kill();
      } catch {
        /* ignore */
      }
      finish({ code: null, stdout, stderr: `${stderr}\n[opencode-hooks] ${path.basename(hookPath)} timed out after ${HOOK_TIMEOUT_MS}ms`, timedOut: true });
    }, HOOK_TIMEOUT_MS);

    child.on("error", (error) => finish({ code: null, stdout, stderr: `${stderr}${error && error.message ? error.message : error}`, spawnError: true }));
    child.stdout.on("data", (chunk) => {
      stdout += chunk.toString();
    });
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString();
    });
    child.on("close", (code) => finish({ code, stdout, stderr }));
    child.stdin.on("error", () => {
      /* the hook may exit without draining stdin */
    });
    child.stdin.end(JSON.stringify(payload));
  });
}

// Run every configured hook for a Claude event whose matcher accepts `names`.
// Returns the aggregate block/rewrite/context outcome. Never throws.
async function runEventHooks(root, eventName, { matcher, payload, hookPath } = {}) {
  const groups = Array.isArray(HOOKS[eventName]) ? HOOKS[eventName] : [];
  const outcome = { code: 0, stdout: "", stderr: "", contexts: [], updatedInput: null, blocked: false, denyReason: null, ran: 0 };
  for (const group of groups) {
    if (!group || typeof group !== "object") continue;
    if (matcher && !matcherMatches(group.matcher, matcher)) continue;
    for (const hook of Array.isArray(group.hooks) ? group.hooks : []) {
      if (!hook || hook.type !== "command" || typeof hook.command !== "string") continue;
      if (hookPath && hook.command.replaceAll("\\", "/") !== hookPath) continue;
      if (!hookConditionHolds(hook.if, root, payload)) continue;
      outcome.ran += 1;
      const result = await runHook(root, path.resolve(root, hook.command), payload);
      if (result.stdout) outcome.stdout += result.stdout;
      if (result.stderr) outcome.stderr += result.stderr;
      if (result.spawnError || result.timedOut) continue;
      if (result.code === 2) {
        outcome.code = 2;
        outcome.blocked = true;
        if (result.stderr.trim()) outcome.denyReason = result.stderr.trim();
      }
      const parsed = parseJsonOutput(result.stdout);
      const isHookObject = parsed !== null && typeof parsed === "object" && !Array.isArray(parsed);
      if (!isHookObject) {
        // Claude Code adds the plain-text stdout of an exit-0 UserPromptSubmit hook
        // to the prompt context; only JSON objects are hook-control output.
        if (eventName === "UserPromptSubmit" && result.code === 0) {
          const text = typeof result.stdout === "string" ? result.stdout.trim() : "";
          if (text) outcome.contexts.push(text);
        }
        continue;
      }
      const specific = parsed.hookSpecificOutput;
      if (!specific || typeof specific !== "object") continue;
      if (specific.permissionDecision === "deny") {
        outcome.code = 2;
        outcome.blocked = true;
        outcome.denyReason = specific.permissionDecisionReason || outcome.denyReason || result.stderr.trim() || "Denied by .claude hook";
      }
      if (specific.updatedInput && typeof specific.updatedInput === "object") {
        outcome.updatedInput = { ...(outcome.updatedInput || {}), ...specific.updatedInput };
      }
      if (typeof specific.additionalContext === "string" && specific.additionalContext.trim()) {
        outcome.contexts.push(specific.additionalContext);
      }
    }
  }
  return outcome;
}

function warn(context, result) {
  if (!result || !result.stderr) return;
  const detail = result.stderr.trim();
  if (!detail) return;
  if (!result.spawnError && !result.timedOut && result.code !== 2) return;
  process.stderr.write(`[opencode-hooks] ${context}: ${detail}\n`);
}

function sessionKey(sessionID) {
  return sessionID || "default";
}

// opencode validates every user part before it saves the message: a part without
// id, sessionID and messageID fails the whole prompt. An injected context part takes
// the message identity from its first part (falling back to the message and the hook
// input), and a unique id made from the first part's id plus a 2-digit index.
// Returns null when no identity is available, so the caller drops the context
// instead of failing the prompt.
function contextPartIdentity(hookInput, output, parts) {
  const first = parts.find((part) => part && typeof part.id === "string" && part.id);
  const message = output && output.message && typeof output.message === "object" ? output.message : {};
  const sessionID = (first && first.sessionID) || message.sessionID || (hookInput && hookInput.sessionID) || "";
  const messageID = (first && first.messageID) || message.id || (hookInput && hookInput.messageID) || "";
  if (!first || !sessionID || !messageID) return null;
  return { baseId: first.id, sessionID, messageID };
}

function nextPartId(baseId, parts) {
  const taken = new Set(parts.map((part) => part && part.id));
  for (let index = parts.length; ; index += 1) {
    const id = `${baseId}${String(index).padStart(2, "0")}`;
    if (!taken.has(id)) return id;
  }
}

export const EasyClaudeHooks = async (input) => {
  const seed = input && (input.directory || input.worktree) ? input.directory || input.worktree : process.cwd();
  const root = findRoot(seed);
  const startedSessions = new Set();
  const sessionStartContext = new Map();
  // Pre-tool callbacks can rewrite args, but have no model-context output. Hold
  // trusted hook context for the tool's after-callback, or for the next model
  // request when that callback cannot deliver it (a blocked or failed tool).
  const pendingToolContext = new Map();
  function queueToolContext(sessionID, contexts) {
    if (typeof sessionID !== "string" || !sessionID.trim() || contexts.length === 0) return;
    const key = sessionKey(sessionID);
    if (!pendingToolContext.has(key) && pendingToolContext.size >= 256) {
      process.stderr.write("[opencode-hooks] PreToolUse: pending context session limit reached\n");
      return;
    }
    const pending = pendingToolContext.get(key) || new Set();
    let bytes = [...pending].reduce((total, text) => total + Buffer.byteLength(text), 0);
    for (const text of contexts) {
      if (pending.has(text)) continue;
      const size = Buffer.byteLength(text);
      if (pending.size >= 32 || bytes + size > 65536) {
        process.stderr.write("[opencode-hooks] PreToolUse: pending context payload limit reached\n");
        continue;
      }
      pending.add(text);
      bytes += size;
    }
    if (pending.size > 0) pendingToolContext.set(key, pending);
  }
  // Child (delegated) sessions, learned from the SessionInfo on created/updated events. session.idle
  // carries only the session id, so this is how a child going idle is told apart from the main one.
  const delegatedSessions = new Set();

  function rememberSessionKind(props) {
    const info = props.info && typeof props.info === "object" ? props.info : null;
    if (info && info.id && info.parentID) delegatedSessions.add(sessionKey(info.id));
  }

  async function ensureSessionStart(sessionID, source) {
    const key = sessionKey(sessionID);
    if (startedSessions.has(key)) return;
    startedSessions.add(key);
    const payload = { hook_event_name: "SessionStart", source, session_id: sessionID, cwd: seed };
    const result = await runEventHooks(root, "SessionStart", { matcher: [source], payload });
    if (result.contexts.length > 0) sessionStartContext.set(key, result.contexts);
    warn("SessionStart", result);
  }

  return {
    event: async ({ event }) => {
      if (!event || typeof event.type !== "string") return;
      const props = event.properties && typeof event.properties === "object" ? event.properties : {};
      const sessionID = props.sessionID || props.session_id || (props.info && props.info.id) || "";
      switch (event.type) {
        case "session.created":
          rememberSessionKind(props);
          await ensureSessionStart(sessionID, "startup");
          break;
        case "session.updated":
          rememberSessionKind(props);
          break;
        case "session.compacted":
          recordProtocolCompaction(root, sessionID);
          pendingToolContext.delete(sessionKey(sessionID));
          sessionStartContext.delete(sessionKey(sessionID));
          startedSessions.delete(sessionKey(sessionID));
          await ensureSessionStart(sessionID, "compact");
          break;
        case "session.deleted": {
          pendingToolContext.delete(sessionKey(sessionID));
          startedSessions.delete(sessionKey(sessionID));
          sessionStartContext.delete(sessionKey(sessionID));
          delegatedSessions.delete(sessionKey(sessionID));
          // Every ended session is forwarded so per-session cleanup hooks always run; only the
          // main-session alert depends on knowing which conversation ended. OpenCode includes
          // SessionInfo on session.deleted, and parentID marks a delegated session: carry it as
          // agent_id, the same marker Claude puts on a subagent event. Without SessionInfo the
          // kind is unknown, so mark it and let the notification router withhold the alert.
          const sessionInfo = props.info && typeof props.info === "object" ? props.info : null;
          const payload = { hook_event_name: "SessionEnd", reason: "exit", session_id: sessionID, cwd: seed };
          if (!sessionInfo) payload.conversation_kind = "unknown";
          else if (sessionInfo.parentID) payload.agent_id = sessionID;
          const result = await runEventHooks(root, "SessionEnd", { payload });
          warn("SessionEnd", result);
          break;
        }
        case "session.idle": {
          // A child session goes idle each time its delegated work finishes; mark it with agent_id
          // so the notification router keeps the turn-complete alert for the main session only.
          const payload = { hook_event_name: "Stop", session_id: sessionID, cwd: seed };
          if (delegatedSessions.has(sessionKey(sessionID))) payload.agent_id = sessionID;
          const result = await runEventHooks(root, "Stop", { payload });
          warn("Stop", result);
          break;
        }
        case "permission.asked": {
          const permission = typeof props.permission === "string" ? props.permission : "";
          const result = await runEventHooks(root, "Notification", {
            matcher: ["permission_prompt"],
            payload: {
              hook_event_name: "Notification",
              notification_type: "permission_prompt",
              message: permission ? `opencode needs permission: ${permission}` : "opencode needs permission",
              session_id: sessionID,
              cwd: seed,
            },
          });
          warn("permission.asked", result);
          break;
        }
        case "question.asked": {
          const result = await runEventHooks(root, "Notification", {
            matcher: ["AskUserPrompt"],
            payload: { hook_event_name: "AskUserPrompt", tool_name: "AskUserQuestion", session_id: sessionID, cwd: seed },
          });
          warn("question.asked", result);
          break;
        }
        default:
          break;
      }
    },

    "tool.execute.before": async (hookInput, output) => {
      const tool = hookInput && hookInput.tool;
      const names = claudeToolNames(tool);
      const result = await runEventHooks(root, "PreToolUse", {
        matcher: names,
        payload: {
          hook_event_name: "PreToolUse",
          tool_name: names[0] || tool,
          tool_input: toClaudeToolInput(tool, output && output.args),
          // The question tool emits question.asked once it is waiting for an
          // answer. Defer its PreToolUse notification so users get one alert.
          notification_deferred: tool === "question",
          session_id: hookInput && hookInput.sessionID,
          cwd: seed,
        },
      });
      queueToolContext(hookInput && hookInput.sessionID, result.contexts);
      if (result.updatedInput && output && output.args && typeof output.args === "object") {
        applyUpdatedInput(output.args, result.updatedInput);
      }
      if (result.blocked) {
        throw new Error((result.denyReason || "Blocked by a .claude hook").trim());
      }
      warn(`PreToolUse:${tool}`, result);
    },

    "tool.execute.after": async (hookInput, output) => {
      const tool = hookInput && hookInput.tool;
      const names = claudeToolNames(tool);
      const result = await runEventHooks(root, "PostToolUse", {
        matcher: names,
        payload: {
          hook_event_name: "PostToolUse",
          tool_name: names[0] || tool,
          tool_input: toClaudeToolInput(tool, hookInput && hookInput.args),
          // Claude's PostToolUse contract field is `tool_response` (an OBJECT) — hooks read it
          // (e.g. `.claude/hooks/lib/file-conventions.cjs` checks `tool_response.success === false`).
          // opencode exposes the result as `output.output`; emit the object shape so those readers
          // are not silently fed `undefined`. `tool.execute.after` only fires once the tool has
          // completed, so `success` is true here; keep `tool_result` for the repo's own
          // `.claude/hooks/lib/stdin-parser.cjs` normalizer.
          tool_response: {
            success: true,
            output: output && typeof output.output === "string" ? output.output : "",
          },
          tool_result: output && typeof output.output === "string" ? output.output : "",
          session_id: hookInput && hookInput.sessionID,
          cwd: seed,
        },
      });
      if (output && typeof output.output === "string") {
        // Tool output stays in the conversation; a system-prompt push lasts one model request.
        // So this callback is the primary sink for pending pre-tool context: take it here, in
        // one step with its removal, and leave the system transform only what no tool carried.
        const key = sessionKey(hookInput && hookInput.sessionID);
        const contexts = [...(pendingToolContext.get(key) || []), ...result.contexts];
        pendingToolContext.delete(key);
        if (contexts.length > 0) output.output += `\n\n${contexts.join("\n\n")}`;
      }
      warn(`PostToolUse:${tool}`, result);
    },

    "chat.message": async (hookInput, output) => {
      const sessionID = hookInput && hookInput.sessionID;
      await ensureSessionStart(sessionID, "startup");
      const parts = Array.isArray(output && output.parts) ? output.parts : [];
      const prompt = parts
        .filter((part) => part && part.type === "text" && typeof part.text === "string")
        .map((part) => part.text)
        .join("\n");
      const result = await runEventHooks(root, "UserPromptSubmit", {
        payload: { hook_event_name: "UserPromptSubmit", prompt, session_id: sessionID, cwd: seed },
      });
      if (result.contexts.length > 0) {
        const identity = contextPartIdentity(hookInput, output, parts);
        if (identity) {
          for (const text of result.contexts) {
            const id = nextPartId(identity.baseId, parts);
            parts.push({ id, sessionID: identity.sessionID, messageID: identity.messageID, type: "text", text, synthetic: true });
          }
          if (output) output.parts = parts;
        } else {
          process.stderr.write("[opencode-hooks] UserPromptSubmit: context dropped, the message has no part id, sessionID or messageID\n");
        }
      }
      warn("UserPromptSubmit", result);
    },

    "experimental.chat.system.transform": async (hookInput, output) => {
      const sessionID = hookInput && hookInput.sessionID;
      // A developer can change skill selection between turns. Never replay the cached startup
      // policy into the system prompt: it could outrank a newer prompt-level reset. The real hook
      // reads effective configuration here for main AND delegated sessions, even without chat.message.
      const policyMarker = "<!-- CK:SKILL-ACTIVATION-POLICY -->";
      const context = (sessionStartContext.get(sessionKey(sessionID)) || []).filter(text => !text.startsWith(policyMarker));
      if (Array.isArray(context) && context.length > 0 && output && Array.isArray(output.system)) {
        output.system.push(...context);
      }
      if (output && Array.isArray(output.system)) {
        const livePolicy = await runEventHooks(root, "SessionStart", {
          matcher: ["resume"],
          hookPath: ".claude/hooks/skill-activation-inject.cjs",
          payload: { hook_event_name: "SessionStart", source: "resume", session_id: sessionID, cwd: seed },
        });
        output.system.push(...livePolicy.contexts);
        warn("SkillActivationPolicy", livePolicy);
        // Fallback sink: pre-tool context that no tool output carried.
        const key = sessionKey(sessionID);
        const pending = pendingToolContext.get(key);
        if (pending) {
          output.system.push(...pending);
          pendingToolContext.delete(key);
        }
      }
    },

    "permission.ask": async (permission, output) => {
      const result = await runEventHooks(root, "PermissionRequest", {
        payload: {
          hook_event_name: "PermissionRequest",
          tool_name: permission && (permission.tool || permission.toolName),
          session_id: permission && permission.sessionID,
          cwd: seed,
        },
      });
      if (result.blocked) output.status = "deny";
      else if (result.updatedInput && output) output.status = "allow";
      warn("PermissionRequest", result);
    },
  };
};
